 jsonb_build_object('heading','Compreensão antes da produção','content',jsonb_build_array('Apresente significado por imagem, objeto, gesto consentido, tradução curta e áudio regulável; depois modele som, palavra e frase.','Fala e repetição em público são opcionais. Aceite apontamento, seleção, ordenação, comunicação alternativa, áudio privado, digitação ou escrita.','Trate sotaques e variedades do inglês com respeito; avalie inteligibilidade e compreensão, não imitação de sotaque nativo.')),
 jsonb_build_object('heading','Privacidade, cultura e bem-estar','content',jsonb_build_array('Use nomes, famílias, casas, rotinas, cidades, viagens, escolas e perfis fictícios; nunca peça endereço, geolocalização, documento, foto de casa, rota, renda, religião, diagnóstico ou história familiar.','Temas de corpo, roupa, alimentação, saúde e esporte não podem gerar comparação corporal, dieta, meta física ou exposição de hábito pessoal.','Use áudio e textos autorizados, licenciados ou em domínio público conforme aplicável; não reproduza letras ou obras integrais protegidas.')),
